import "server-only";

import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

import Anthropic from "@anthropic-ai/sdk";
import { betaZodOutputFormat } from "@anthropic-ai/sdk/helpers/beta/zod";
import { z } from "zod";

import { isMockMode } from "../config";
import { cloneFor, githubGet, githubToken, localClones, mapLimit, repoKey, run } from "./sources";

/**
 * AI summaries of what each repo's code does, generated by Claude from the file tree,
 * README, manifests and entry points.
 *
 * Each summary is saved next to the code and stamped with the commit it describes:
 *   - local clone  → <clone>/.railway-inspector/summary.json, listed in that clone's
 *                    .git/info/exclude so it never shows up in `git status` or a commit
 *   - GitHub only  → data/code-summaries/<owner>__<name>.json in this app
 * A summary is reused until the commit (or, for a local clone, the uncommitted diff) changes.
 */

export const SUMMARY_MODEL = "claude-opus-5-5";
const DIR_NAME = ".railway-inspector";
const DATA_DIR = path.join(process.env.AUDIT_LOG_DIR ?? path.join(process.cwd(), "data"), "code-summaries");

export const AiSummarySchema = z.object({
  name: z.string().describe("A short, human name for the app (2-5 words), e.g. 'Bank statement converter'"),
  summary: z.string().describe("One or two plain sentences: what the app does and for whom"),
  stack: z.array(z.string()).describe("Main languages, frameworks and runtimes, e.g. ['Python', 'Flask']"),
  features: z.array(z.string()).describe("Up to 6 things the app actually does, from the code"),
  services: z.array(z.string()).describe("External APIs and services it calls, e.g. ['OpenAI', 'Stripe', 'Firestore']"),
  entrypoint: z.string().describe("How it starts in production, e.g. 'gunicorn app:app' or 'next start'"),
  keywords: z.array(z.string()).describe("Up to 10 search keywords someone might use to find this app"),
});
export type AiSummary = z.infer<typeof AiSummarySchema>;

export type Fingerprint = { commit: string; dirty: string | null };
export type StoredSummary = {
  version: 1;
  repo: string;
  fingerprint: Fingerprint;
  generatedAt: string;
  model: string;
  summary: AiSummary;
};
export type SummaryStatus = { stored: StoredSummary | null; current: Fingerprint | null; stale: boolean; location: string };

/** Claude credentials: ANTHROPIC_API_KEY or ANTHROPIC_AUTH_TOKEN. Off in demo mode and on Vercel. */
export function aiSummariesAvailable(): boolean {
  if (isMockMode() || process.env.VERCEL === "1") return false;
  return !!(process.env.ANTHROPIC_API_KEY?.trim() || process.env.ANTHROPIC_AUTH_TOKEN?.trim());
}

// ── Where the code is, and which version ────────────────────────────────────

type Target = { kind: "local"; repo: string; dir: string } | { kind: "github"; repo: string; token: string };

async function target(repo: string): Promise<Target | null> {
  const found = cloneFor(repo, await localClones());
  if (found) return { kind: "local", repo, dir: found.clone.dir };
  const token = await githubToken();
  return token ? { kind: "github", repo, token } : null;
}

const sha1 = (text: string) => createHash("sha1").update(text).digest("hex").slice(0, 16);

async function fingerprint(t: Target): Promise<Fingerprint> {
  if (t.kind === "github") {
    const commit = (await githubGet<string>(t.token, `/repos/${t.repo}/commits/HEAD`, "application/vnd.github.sha")).trim();
    return { commit, dirty: null };
  }
  const [{ stdout: head }, { stdout: diff }, { stdout: untracked }] = await Promise.all([
    run("git", ["-C", t.dir, "rev-parse", "HEAD"], { timeout: 10_000 }),
    run("git", ["-C", t.dir, "diff", "HEAD", "--stat"], { timeout: 15_000, maxBuffer: 4 * 1024 * 1024 }),
    run("git", ["-C", t.dir, "ls-files", "--others", "--exclude-standard"], { timeout: 15_000, maxBuffer: 4 * 1024 * 1024 }),
  ]);
  const local = `${diff}\n${untracked.split("\n").filter((f) => !f.startsWith(`${DIR_NAME}/`)).join("\n")}`.trim();
  return { commit: head.trim(), dirty: local ? sha1(local) : null };
}

function storePath(t: Target): string {
  return t.kind === "local" ? path.join(t.dir, DIR_NAME, "summary.json") : path.join(DATA_DIR, `${repoKey(t.repo).replace("/", "__")}.json`);
}

async function readStored(file: string): Promise<StoredSummary | null> {
  try {
    const data = JSON.parse(await readFile(file, "utf8")) as StoredSummary;
    return data.version === 1 && AiSummarySchema.safeParse(data.summary).success ? data : null;
  } catch {
    return null;
  }
}

/** Keep the summary folder out of git without touching the repo's own .gitignore. */
async function excludeFromGit(dir: string) {
  const { stdout } = await run("git", ["-C", dir, "rev-parse", "--git-path", "info/exclude"], { timeout: 10_000 });
  const file = path.resolve(dir, stdout.trim());
  let current = "";
  try {
    current = await readFile(file, "utf8");
  } catch {}
  if (current.split("\n").some((l) => l.trim() === `${DIR_NAME}/`)) return;
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(file, `${current}${current && !current.endsWith("\n") ? "\n" : ""}# railway-billing-inspector AI summary\n${DIR_NAME}/\n`);
}

const sameFingerprint = (a: Fingerprint, b: Fingerprint) => a.commit === b.commit && a.dirty === b.dirty;

const statusCache = new Map<string, { at: number; status: SummaryStatus | null }>();

/** Stored summary + whether the code has changed since. Cached for a minute. */
export async function summaryStatus(repo: string): Promise<SummaryStatus | null> {
  const key = repoKey(repo);
  const cached = statusCache.get(key);
  if (cached && Date.now() - cached.at < 60_000) return cached.status;
  let status: SummaryStatus | null = null;
  try {
    const t = await target(repo);
    if (t) {
      const location = storePath(t);
      const [stored, current] = await Promise.all([readStored(location), fingerprint(t).catch(() => null)]);
      status = { stored, current, stale: !!stored && !!current && !sameFingerprint(stored.fingerprint, current), location };
    }
  } catch {}
  statusCache.set(key, { at: Date.now(), status });
  return status;
}

export async function summaryStatuses(repos: string[]): Promise<Map<string, SummaryStatus>> {
  const out = new Map<string, SummaryStatus>();
  const unique = [...new Map(repos.map((r) => [repoKey(r), r])).values()];
  await mapLimit(unique, 8, async (r) => {
    const s = await summaryStatus(r);
    if (s) out.set(repoKey(r), s);
  });
  return out;
}

// ── Reading the code ────────────────────────────────────────────────────────

const MANIFESTS = /(^|\/)(package\.json|requirements\.txt|pyproject\.toml|Pipfile|setup\.py|go\.mod|Cargo\.toml|Gemfile|composer\.json|Dockerfile|docker-compose\.ya?ml|Procfile|railway\.(json|toml)|nixpacks\.toml|vercel\.json|next\.config\.[jt]s|app\.json|\.env\.example)$/i;
const ENTRY = /(^|\/)(main|app|server|index|wsgi|asgi|manage|bot|worker|api|routes?)\.(py|[jt]sx?|mjs|go|rb|php)$/i;
const README = /^readme(\.(md|markdown|mdx|txt|rst))?$/i;
const SKIP = /(^|\/)(node_modules|\.git|dist|build|out|\.next|vendor|venv|\.venv|__pycache__|coverage|migrations)\//;
const MAX_FILE = 12_000;
const MAX_TOTAL = 90_000;

function pickFiles(paths: string[]): string[] {
  const usable = paths.filter((p) => !SKIP.test(p));
  const depth = (p: string) => p.split("/").length;
  const byDepth = (a: string, b: string) => depth(a) - depth(b) || a.localeCompare(b);
  const readme = usable.filter((p) => README.test(p)).sort(byDepth).slice(0, 1);
  const manifests = usable.filter((p) => MANIFESTS.test(p) && depth(p) <= 2).sort(byDepth).slice(0, 8);
  const entries = usable.filter((p) => ENTRY.test(p) && depth(p) <= 3).sort(byDepth).slice(0, 6);
  return [...new Set([...readme, ...manifests, ...entries])];
}

async function listFiles(t: Target, commit: string): Promise<string[]> {
  if (t.kind === "local") {
    const { stdout } = await run("git", ["-C", t.dir, "ls-files", "--cached", "--others", "--exclude-standard"], { timeout: 15_000, maxBuffer: 16 * 1024 * 1024 });
    return stdout.split("\n").filter((p) => p && !p.startsWith(`${DIR_NAME}/`));
  }
  const tree = await githubGet<{ tree: { path: string; type: string }[] }>(t.token, `/repos/${t.repo}/git/trees/${commit}?recursive=1`);
  return tree.tree.filter((e) => e.type === "blob").map((e) => e.path);
}

async function readCodeFile(t: Target, file: string, commit: string): Promise<string> {
  if (t.kind === "local") return readFile(path.join(t.dir, file), "utf8");
  return githubGet<string>(t.token, `/repos/${t.repo}/contents/${file.split("/").map(encodeURIComponent).join("/")}?ref=${commit}`, "application/vnd.github.raw+json");
}

async function codeContext(t: Target, commit: string): Promise<string> {
  const all = await listFiles(t, commit);
  const tree = all.filter((p) => !SKIP.test(p)).slice(0, 400);
  const parts = [`Repository: ${t.repo}`, `File tree (${all.length} files${all.length > tree.length ? `, first ${tree.length} shown` : ""}):\n${tree.join("\n")}`];
  let total = parts.join("\n").length;
  for (const file of pickFiles(all)) {
    if (total >= MAX_TOTAL) break;
    try {
      let text = await readCodeFile(t, file, commit);
      if (text.includes("\0")) continue;
      if (text.length > MAX_FILE) text = `${text.slice(0, MAX_FILE)}\n…(truncated)`;
      const block = `\n--- ${file} ---\n${text}`;
      parts.push(block);
      total += block.length;
    } catch {}
  }
  return parts.join("\n");
}

// ── Claude ──────────────────────────────────────────────────────────────────

const SYSTEM = `You write short catalog entries for a developer's deployed apps. The developer has many apps on Railway with auto-generated names like "steadfast-fascination" and has forgotten which is which. From the repository contents, describe what the app actually does, judged by the code, not just the README (READMEs are often template boilerplate - say so only if the code really is just the template). Be concrete and plain: name the real inputs, outputs and services. No marketing language.`;

let client: Anthropic | null = null;

async function summarizeWithClaude(context: string): Promise<AiSummary> {
  client ??= new Anthropic();
  const response = await client.beta.messages.parse({
    model: SUMMARY_MODEL,
    max_tokens: 4000,
    betas: ["server-side-fallback-2026-07-01"],
    fallbacks: "default",
    output_config: { effort: "low", format: betaZodOutputFormat(AiSummarySchema) },
    system: SYSTEM,
    messages: [{ role: "user", content: context }],
  });
  if (response.stop_reason === "refusal") throw new Error("Claude declined to summarize this repo.");
  if (!response.parsed_output) throw new Error(`No summary returned (stop reason: ${response.stop_reason}).`);
  return response.parsed_output;
}

/** Summarize one repo unless its saved summary still matches the code. Returns what was done. */
export async function summarizeRepo(repo: string, force = false): Promise<"fresh" | "updated" | "created"> {
  const t = await target(repo);
  if (!t) throw new Error("Repo isn't readable: no local clone and no GitHub token.");
  const location = storePath(t);
  const [stored, current] = await Promise.all([readStored(location), fingerprint(t)]);
  if (!force && stored && sameFingerprint(stored.fingerprint, current)) return "fresh";

  const summary = await summarizeWithClaude(await codeContext(t, current.commit));
  const record: StoredSummary = { version: 1, repo, fingerprint: current, generatedAt: new Date().toISOString(), model: SUMMARY_MODEL, summary };
  if (t.kind === "local") await excludeFromGit(t.dir);
  await mkdir(path.dirname(location), { recursive: true });
  await writeFile(location, `${JSON.stringify(record, null, 2)}\n`);
  statusCache.delete(repoKey(repo));
  return stored ? "updated" : "created";
}

// ── Background job ──────────────────────────────────────────────────────────

export type SummaryJob = {
  running: boolean;
  startedAt: string | null;
  finishedAt: string | null;
  total: number;
  done: number;
  current: string[];
  created: number;
  updated: number;
  fresh: number;
  failed: { repo: string; error: string }[];
};

const job: SummaryJob = { running: false, startedAt: null, finishedAt: null, total: 0, done: 0, current: [], created: 0, updated: 0, fresh: 0, failed: [] };

export const summaryJob = (): SummaryJob => ({ ...job, current: [...job.current], failed: [...job.failed] });

/** Start summarizing in the background (one job at a time). Returns false if one is already running. */
export function startSummaryJob(repos: string[], force = false): boolean {
  if (job.running || repos.length === 0 || !aiSummariesAvailable()) return false;
  const unique = [...new Map(repos.map((r) => [repoKey(r), r])).values()];
  Object.assign(job, { running: true, startedAt: new Date().toISOString(), finishedAt: null, total: unique.length, done: 0, current: [], created: 0, updated: 0, fresh: 0, failed: [] });
  void mapLimit(unique, 3, async (repo) => {
    job.current.push(repo);
    try {
      job[await summarizeRepo(repo, force)]++;
    } catch (error) {
      const message = error instanceof Anthropic.AuthenticationError ? "Claude rejected the API key." : error instanceof Error ? error.message : String(error);
      job.failed.push({ repo, error: message });
    } finally {
      job.current = job.current.filter((r) => r !== repo);
      job.done++;
    }
  }).finally(() => {
    job.running = false;
    job.finishedAt = new Date().toISOString();
  });
  return true;
}
